## Steps to reproduce.

Using a nextjs app create a new api route `api/test/route.ts`

Paste this code inside:
```typescript
import { DynamicStructuredTool, formatToOpenAITool } from "langchain/tools";

import { z } from "zod";

export const runtime = "edge";

export async function GET(request: Request) {
  const imageTool = new DynamicStructuredTool({
    name: "get_current_weather",
    description: "Get the current weather in a given location",
    func: async ({ location }) => {
      if (location.toLowerCase().includes("tokyo")) {
        return JSON.stringify({ location, temperature: "10", unit: "celsius" });
      } else if (location.toLowerCase().includes("san francisco")) {
        return JSON.stringify({
          location,
          temperature: "72",
          unit: "fahrenheit",
        });
      } else {
        return JSON.stringify({ location, temperature: "22", unit: "celsius" });
      }
    },
    schema: z.object({
      location: z
        .string()
        .describe("The city and state, e.g. San Francisco, CA"),
      unit: z.enum(["celsius", "fahrenheit"]),
    }),
  });
  return new Response(JSON.stringify(formatToOpenAITool(imageTool)), {
    headers: { "Content-Type": "text/html; charset=utf-8" },
  });
}
```

